//! Port of utils/xml/SUMOXMLDefinitions.{h,cpp}
//! Enums and tables are generated by tools/gen_xml_definitions.py; C++ static members of
//! SUMOXMLDefinitions are module items with their C++ names, so
//! `use utils::xml::sumo_xml_definitions as SUMOXMLDefinitions;` reads like the C++.
// shortcut: TL() file-extension descriptions are not translated, add when gettext support lands
#![allow(non_camel_case_types, non_upper_case_globals, clippy::upper_case_acronyms)]
use super::stand_ins::tokenize_white;
use crate::common::string_utils;

include!("sumo_xml_definitions_gen.rs");

pub const SUMO_PARAM_ORIGID: &str = "origId";
pub const SUMO_PARAM_REMOVED_NODES: &str = "removedNodeIds";

/// all allowed characters for phase state
pub const ALLOWED_TLS_LINKSTATES: &str = "GgsruYyoO";

/// typedef std::bitset<96> SumoXMLAttrMask
#[derive(Debug, Clone, Copy, PartialEq, Eq, Default)]
pub struct SumoXMLAttrMask(pub u128);
impl SumoXMLAttrMask {
    pub const SIZE: i32 = 96;
    pub fn none(&self) -> bool {
        self.0 == 0
    }
    pub fn test(&self, bit: i32) -> bool {
        (self.0 >> bit) & 1 != 0
    }
    pub fn set(&mut self, bit: i32) {
        self.0 |= 1 << bit;
    }
    pub fn set_all(&mut self) {
        self.0 = (1u128 << Self::SIZE) - 1;
    }
}

pub fn get_junction_id_from_internal_edge(internal_edge: &str) -> String {
    debug_assert!(internal_edge.starts_with(':'));
    let end = internal_edge.rfind('_').unwrap_or(internal_edge.len());
    internal_edge[1..end.max(1)].to_string()
}

pub fn get_edge_id_from_lane(lane_id: &str) -> String {
    lane_id[..lane_id.rfind('_').unwrap_or(lane_id.len())].to_string()
}

pub fn get_index_from_lane(lane_id: &str) -> Result<i32, string_utils::NumberFormatException> {
    string_utils::to_int(&lane_id[lane_id.rfind('_').map_or(0, |i| i + 1)..])
}

fn has_none_of(value: &str, chars: &str) -> bool {
    !value.contains(|c| chars.contains(c))
}

pub fn is_valid_net_id(value: &str) -> bool {
    !value.is_empty() && has_none_of(value, " \t\n\r|\\'\";,<>&") && !value.starts_with(':')
}
pub fn is_valid_vehicle_id(value: &str) -> bool {
    !value.is_empty() && has_none_of(value, " \t\n\r|\\'\";,<>&")
}
pub fn is_valid_type_id(value: &str) -> bool {
    !value.is_empty() && has_none_of(value, " \t\n\r|\\'\";,<>&")
}
pub fn is_valid_additional_id(value: &str) -> bool {
    !value.is_empty() && has_none_of(value, " \t\n\r|\\'\";,<>&")
}
pub fn is_valid_detector_id(value: &str) -> bool {
    // special case: ' ' allowed
    !value.is_empty() && has_none_of(value, "\t\n\r|\\'\";,<>&")
}
pub fn is_valid_attribute(value: &str) -> bool {
    has_none_of(value, "\t\n\r&|\\'\"<>")
}
pub fn is_valid_filename(value: &str) -> bool {
    has_none_of(value, "\t\n\r@$%^&|{}*'\";<>")
}
pub fn is_valid_list_of_net_ids(value: &str) -> bool {
    let ids = tokenize_white(value);
    !ids.is_empty() && ids.iter().all(|i| is_valid_net_id(i))
}
pub fn is_valid_list_of_type_id(value: &str) -> bool {
    is_valid_list_of_type_id_vec(&tokenize_white(value))
}
pub fn is_valid_list_of_type_id_vec<S: AsRef<str>>(type_ids: &[S]) -> bool {
    !type_ids.is_empty() && type_ids.iter().all(|t| is_valid_type_id(t.as_ref()))
}
pub fn is_valid_parameter_key(value: &str) -> bool {
    // Generic parameters keys cannot be empty
    !value.is_empty() && is_valid_attribute(value)
}

pub fn make_valid_id(value: &str) -> String {
    if value.is_empty() {
        return "_".into();
    }
    // the C++ loop also runs over the terminating '\0' of the literal
    let mut result: String = value.chars().map(|c| if " \t\n\r|\\'\";,<>&\0".contains(c) { '_' } else { c }).collect();
    if result.starts_with(':') {
        result.replace_range(0..1, "_");
    }
    result
}

#[cfg(test)]
mod tests {
    use super::*;
    #[test]
    fn tables() {
        assert_eq!(Tags.get_string(SUMO_TAG_NET), "net");
        assert_eq!(Tags.get("edge").unwrap(), SUMO_TAG_EDGE);
        assert_eq!(Attrs.get_string(SUMO_ATTR_ID), "id");
        assert_eq!(Attrs.get_string(SUMO_ATTR_NOTHING), "");
        assert_eq!(Attrs.get_string(SUMO_ATTR_COMMAND), if cfg!(windows) { "commandWindows" } else { "commandPosix" });
        assert_eq!(NodeTypes.get("priority").unwrap(), SumoXMLNodeType::PRIORITY);
        assert_eq!(NodeTypes.get_string(SumoXMLNodeType::DEAD_END_DEPRECATED), "DEAD_END");
        assert_eq!(LinkStates.get_string(LINKSTATE_TL_GREEN_MAJOR), "G");
        assert_eq!(LINKSTATE_TL_GREEN_MAJOR, 'G' as i32);
        assert_eq!(LaneChangeActions.get_string(LCA_BLOCKED), "blocked");
        assert_eq!(TrafficLightTypes.get("actuated").unwrap(), TrafficLightType::ACTUATED);
        assert_eq!(MeanDataFileExtensions.get_string(MeanDataFileExtension::ADD), "Mean data files (*.add.xml,*.add.xml.gz)");
        // std::map<POIIcon, ...> orders by value, NONE = 0 declared last comes first
        assert_eq!(POIIcons.get_values()[0], POIIcon::NONE);
        assert_eq!(Tags.get("x").unwrap_err().to_string(), "String 'x' not found.");
        assert_eq!(ALLOWED_TLS_LINKSTATES.len(), 9);
    }
    #[test]
    fn ids() {
        assert!(is_valid_net_id("a_b"));
        assert!(!is_valid_net_id(":a"));
        assert!(!is_valid_net_id("a b"));
        assert!(is_valid_detector_id("a b"));
        assert_eq!(make_valid_id(":a b"), "_a_b");
        assert_eq!(make_valid_id(""), "_");
        assert_eq!(get_edge_id_from_lane("e_1_0"), "e_1");
        assert_eq!(get_index_from_lane("e_1_0").unwrap(), 0);
        assert_eq!(get_junction_id_from_internal_edge(":J0_3"), "J0");
        assert!(is_valid_list_of_type_id("a b"));
        assert!(!is_valid_list_of_net_ids(""));
    }
}
